using System;using System.IO;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {static class RemoteValidation {public static int Run(){string dir=Environment.GetEnvironmentVariable("OREUMMOK_DATA_DIR"),url=Environment.GetEnvironmentVariable("OREUMMOK_QA_REMOTE_URL");Uri host;if(String.IsNullOrEmpty(dir)||!dir.Contains("qa-native")||!Uri.TryCreate(url,UriKind.Absolute,out host)||host.Host!="127.0.0.1")throw new Exception("Remote QA requires a dedicated loopback fixture.");using(var b=new Bridge(true)){b.RemoteUrl=url;b.Call("login",J.Row("username","worker","password","QA-Remote-Password-157"));D data=b.Call("load");if(J.Rows(J.Obj(data["state"]),"customers").Count!=0||J.Rows(J.Obj(data["state"]),"tasks").Count!=1)throw new Exception("Remote data projection failed");bool denied=false;try{b.Call("users");}catch{denied=true;}if(!denied)throw new Exception("Remote privilege check failed");b.Call("logout");File.WriteAllText(Path.Combine(dir,"remote-test.json"),"{\"remoteLogin\":true,\"projection\":true,\"adminDenied\":true}");}return 0;}}}
